        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] strengths = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            strengths[i] = (long) in.nval;
        }
        int[] ans = streamRanks(strengths);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.length; i++) sb.append(ans[i]).append(i + 1 < ans.length ? " " : "\n");
        System.out.print(sb);
    }
}

