def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([5, 4, 6, 1]), fmt([3, 3, 3]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]),
             fmt([10**9, 1, 10**9, 1]), fmt([2, 7, 7, 2, 9, 7])]
    for n in (2, 4, 6, 9, 14, 20, 30):
        for hi in (3, 10, 10**9):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt(list(range(1, N + 1))))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt([rng.randint(1, 50) for _ in range(N)]))
    return tests
